      .getElementById("opt-in")
      .addEventListener("click", () => resolve([{ purpose, provider, status: OptIn }]), {
        once: true,
      });

    // user clicks button that revokes consent
    document
      .getElementById("opt-out")
      .addEventListener("click", () => resolve([{ purpose, provider, status: OptOut }]), {
        once: true,
      });
  }),
}).then(() => {
  // set the log level during sitemap development to see potential problems
  SalesforceInteractions.log.level = "debug";

  const {
    cashDom,
    listener,
    resolvers,
    sendEvent,
    util,
    CartInteractionName,
    CatalogObjectInteractionName,
    OrderInteractionName,
